grid = [[7,7,7,5,7,7,7,7,5,5,7,7,7,7,7,7,7,7,7,5,7,7,7,7,7,7],[7,7,7,7,5,5,7,7,7,7,7,5,5,7,7,7,7,7,7,7,5,7,7,7,7,7],[7,7,7,7,7,7,5,7,7,7,5,7,7,5,7,7,7,5,7,7,7,7,7,7,7,7],[7,7,7,7,7,7,7,7,7,7,7,5,7,7,7,7,7,7,7,7,7,7,5,7,7,7]]
orig=[r[:] for r in grid]
# Fill spans between same-color markers in each row and column.
for r,row in enumerate(orig):
    cs=[c for c,v in enumerate(row) if v==5]
    if len(cs)>1:
        for c in range(min(cs),max(cs)+1):
            if grid[r][c]!=5: grid[r][c]=3
for c in range(len(orig[0])):
    rs=[r for r in range(len(orig)) if orig[r][c]==5]
    if len(rs)>1:
        for r in range(min(rs),max(rs)+1):
            if grid[r][c]!=5: grid[r][c]=3
assert len(grid)==4 and all(len(r)==26 for r in grid)
print(grid)
print(''.join(str(len(r)) for r in grid))
